// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {airPort} from "../src/airPort.sol";

contract Recorder {
    uint256 public calls;
    function transferFrom(address, address, uint256) external returns (bool) {
        calls++;
        return true;
    }
}

contract InvMutTest is Test {
    airPort c;
    Recorder rec;

    function setUp() public {
        c = new airPort();
        rec = new Recorder();
    }

    function testFuzz_property(uint256 n, address from, uint256 v) public {
        n = bound(n, 0, 4);
        address[] memory _tos = new address[](n);
        for (uint256 i = 0; i < n; i++) {
            _tos[i] = address(uint160(uint256(keccak256(abi.encodePacked(i)))) );
        }
        bool ok;
        try c.transfer(from, address(rec), _tos, v) {
            ok = true;
        } catch {
            ok = false;
        }
        assertTrue(!ok || rec.calls() > 0);
    }
}
